// Multi-dimension legend showing per-dimension token counts and percentages
function MultiDimensionLegend({
  perDimensionTokens,
  activeDimensions,
  getColorStyles,
  onComponentClick,
}: {
  perDimensionTokens: Record<string, { tokens: Record<string, number>; total: number }>;
  activeDimensions: string[];
  getColorStyles: (component: string) => { classes: string | null; style: React.CSSProperties | null };
  onComponentClick?: (component: string) => void;
}) {
  // Collect all unique components across all active dimensions
  const allComponents = useMemo(() => {
    const set = new Set<string>();
    for (const dimName of activeDimensions) {
      const dim = perDimensionTokens[dimName];
      if (dim) {
        for (const comp of Object.keys(dim.tokens)) {
          set.add(comp);
        }
      }
    }
    // Sort by total tokens across dimensions (descending)
    return [...set].sort((a, b) => {
      const totalA = activeDimensions.reduce((s, d) => s + (perDimensionTokens[d]?.tokens[a] || 0), 0);
      const totalB = activeDimensions.reduce((s, d) => s + (perDimensionTokens[d]?.tokens[b] || 0), 0);
      return totalB - totalA;
    });
  }, [perDimensionTokens, activeDimensions]);

  return (
    <div className="flex flex-col gap-1 min-w-[240px]">
      {/* Header row with dimension names */}
      <div className="flex items-center gap-2 text-xs text-muted-foreground px-2 pb-1 border-b">
        <span className="flex-1" />
        {activeDimensions.map((dimName) => (
          <span key={dimName} className="w-20 text-right font-medium truncate" title={dimName}>
            {dimName}
          </span>
        ))}
      </div>
      {/* Component rows */}
      {allComponents.map((component) => {
        const colorStyles = getColorStyles(component);
        return (
          <button
            key={component}
            onClick={() => onComponentClick?.(component)}
            className={cn(
              "flex items-center gap-2 text-left text-sm py-1 px-2 rounded hover:bg-gray-100 transition-colors",
              onComponentClick && "cursor-pointer"
            )}
          >
            <span
              className={cn("w-4 h-4 flex-shrink-0", colorStyles.classes)}
              style={colorStyles.style || undefined}
            />
            <span className="flex-1 truncate">{component}</span>
            {activeDimensions.map((dimName) => {
              const dim = perDimensionTokens[dimName];
              const tokens = dim?.tokens[component] || 0;
              const pct = dim && dim.total > 0 ? (tokens / dim.total) * 100 : 0;
              return (
                <span key={dimName} className="w-20 text-right text-xs text-muted-foreground tabular-nums">
                  {tokens > 0 ? (
                    <>{tokens.toLocaleString()} <span className="opacity-60">{pct.toFixed(0)}%</span></>
                  ) : (
                    <span className="opacity-30">—</span>
                  )}
                </span>
              );
            })}
          </button>
        );
      })}
    </div>
  );
}

