      prompt: ctx.customPrompt,
      components: ctx.components || [],
      componentMapping: ctx.componentMapping || {},
      componentTimeline: ctx.componentTimeline || [],
      componentColors: ctx.componentColors || {},
    };
  }
  return ctx.dimensions;
}

