      };

      // Run workflow with GenerateSummary event
      await processConversationWorkflow(
        WorkflowEvent.GenerateSummary,
        ctx,
        runner,
        {
          onSummaryChunk: (id, chunk) => {
            setConversations((prev) =>
              prev.map((c) =>
                c.id === id
                  ? { ...c, aiSummary: (c.aiSummary || "") + chunk }
                  : c,
              ),
            );
          },
        },
      );
    } catch (error) {
