if (componentMapping && components && selectedComponents.size > 0 && selectedComponents.size < components.length) {
  let matchesComponent = false;
  // Check legacy/default mapping
  const partComponent = componentMapping[part.id];
  if (partComponent && selectedComponents.has(partComponent)) {
    matchesComponent = true;
  }
  // Check all other dimensions
  if (!matchesComponent && dimensions) {
    for (const dim of Object.values(dimensions)) {
      const dimComponent = dim.componentMapping[part.id];
      if (dimComponent && selectedComponents.has(dimComponent)) {
        matchesComponent = true;
        break;
      }
    }
  }
  if (!matchesComponent) return false;
}

