306→        <WaffleChart
307→          componentTokens={componentTokensForOverview}
308→          totalTokens={filteredTokensTotal}
309→          getColorStyles={(component) => getWaffleStylesForDimensions(component)}
310→          getLabel={(component) => component}
311→          onComponentClick={handleComponentClick}
312→        />
313→      )}
314→
315→      {/* Workflow Diagram - horizontal sequence of messages */}
316→      {messageComponents.length > 0 && (
317→        <div className="mt-6 pt-4 border-t">
318→          <h4 className="text-sm font-medium text-muted-foreground mb-3">
319→            Workflow ({messageComponents.length} messages)
320→          </h4>
321→          <div className="flex flex-wrap gap-0.5">
322→            {messageComponents.map((component, index) => {
323→              const colorStyles = component ? getWaffleStylesForDimensions(component) : null;
324→              return (
325→                <div
326→                  key={index}
327→                  className={cn(
328→                    "w-3 h-3 flex-shrink-0",
329→                    component ? colorStyles?.classes : "bg-gray-200",
330→                  )}
331→                  style={colorStyles?.style || undefined}
332→                  title={`${index + 1}: ${component || "unknown"}`}
333→                />
334→              );
335→            })}
336→          </div>
337→          <div className="mt-3">
338→            <CompactLegend
339→              components={messageComponents}
340→              componentColors={effectiveColors}
341→            />
342→          </div>
343→        </div>
344→      )}
345→    </div>
346→  );
347→}
348→
349→// Multi-dimension legend showing per-dimension token counts and percentages
350→function MultiDimensionLegend({
351→  perDimensionTokens,
352→  activeDimensions,
353→  getColorStyles,
354→  onComponentClick,
355→}: {
356→  perDimensionTokens: Record<string, { tokens: Record<string, number>; total: number }>;
357→  activeDimensions: string[];
358→  getColorStyles: (component: string) => { classes: string | null; style: React.CSSProperties | null };
359→  onComponentClick?: (component: string) => void;
360→}) {
361→  // Collect all unique components across all active dimensions
362→  const allComponents = useMemo(() => {
363→    const set = new Set<string>();
364→    for (const dimName of activeDimensions) {
365→      const dim = perDimensionTokens[dimName];
366→      if (dim) {
367→        for (const comp of Object.keys(dim.tokens)) {
368→          set.add(comp);
369→        }
370→      }
371→    }
372→    // Sort by total tokens across dimensions (descending)
373→    return [...set].sort((a, b) => {
374→      const totalA = activeDimensions.reduce((s, d) => s + (perDimensionTokens[d]?.tokens[a] || 0), 0);
375→      const totalB = activeDimensions.reduce((s, d) => s + (perDimensionTokens[d]?.tokens[b] || 0), 0);
376→      return totalB - totalA;
377→    });
378→  }, [perDimensionTokens, activeDimensions]);
379→
380→  return (
381→    <div className="flex flex-col gap-1 min-w-[240px]">
382→      {/* Header row with dimension names */}
383→      <div className="flex items-center gap-2 text-xs text-muted-foreground px-2 pb-1 border-b">
384→        <span className="flex-1" />
385→        {activeDimensions.map((dimName) => (
386→          <span key={dimName} className="w-20 text-right font-medium truncate" title={dimName}>
387→            {dimName}
388→          </span>
389→        ))}
390→      </div>
391→      {/* Component rows */}
392→      {allComponents.map((component) => {
393→        const colorStyles = getColorStyles(component);
394→        return (
395→          <button
396→            key={component}
397→            onClick={() => onComponentClick?.(component)}
398→            className={cn(
399→              "flex items-center gap-2 text-left text-sm py-1 px-2 rounded hover:bg-gray-100 transition-colors",
400→              onComponentClick && "cursor-pointer"
401→            )}
402→          >
403→            <span
404→              className={cn("w-4 h-4 flex-shrink-0", colorStyles.classes)}
405→              style={colorStyles.style || undefined}
406→            />
407→            <span className="flex-1 truncate">{component}</span>
408→            {activeDimensions.map((dimName) => {
409→              const dim = perDimensionTokens[dimName];
410→              const tokens = dim?.tokens[component] || 0;
411→              const pct = dim && dim.total > 0 ? (tokens / dim.total) * 100 : 0;
412→              return (
413→                <span key={dimName} className="w-20 text-right text-xs text-muted-foreground tabular-nums">
414→                  {tokens > 0 ? (
415→                    <>{tokens.toLocaleString()} <span className="opacity-60">{pct.toFixed(0)}%</span></>
416→                  ) : (
417→                    <span className="opacity-30">—</span>
418→                  )}
419→                </span>
420→              );
421→            })}
422→          </button>
423→        );
424→      })}
425→    </div>
426→  );
427→}
