      };

      // Run workflow with ResumeFromApiKeyPause event
      processConversationWorkflow(
        WorkflowEvent.ResumeFromApiKeyPause,
        ctx,
        runner,
        {
          onSummaryChunk: onSummaryChunk,
          onAnalysisChunk: onAnalysisChunk,
