169→/**
170→ * Download export data as a JSON file
171→ */
172→export function downloadExport(data: SessionExport): void {
173→  const json = JSON.stringify(data, null, 2);
174→  const blob = new Blob([json], { type: "application/json" });
175→  const url = URL.createObjectURL(blob);
176→  const a = document.createElement("a");
177→  a.href = url;
178→  a.download = `context-viewer-export-${new Date().toISOString().split("T")[0]}.json`;
179→  a.click();
180→  URL.revokeObjectURL(url);
181→}
