 1→/**
 2→ * File format definitions - the single source of truth for
 3→ * what file types the app accepts and how to parse them.
 4→ */
 5→
 6→export interface FileFormat {
 7→  extensions: string[];
 8→  parse: (text: string) => unknown;
 9→}
10→
11→// Plain text format (.txt, .md)
12→const plainTextFormat: FileFormat = {
13→  extensions: [".txt", ".md"],
14→  parse: (text) => text,
15→};
16→
17→// JSONL format (.jsonl)
18→const jsonlFormat: FileFormat = {
19→  extensions: [".jsonl"],
20→  parse: (text) => {
21→    const lines = text.trim().split("\n");
22→    return lines.filter((line) => line.trim()).map((line) => JSON.parse(line));
23→  },
24→};
25→
26→// JSON format (.json, .traj)
27→const jsonFormat: FileFormat = {
28→  extensions: [".json", ".traj"],
29→  parse: (text) => JSON.parse(text),
30→};
31→
32→// All formats in priority order
33→const FILE_FORMATS: FileFormat[] = [plainTextFormat, jsonlFormat, jsonFormat];
34→
35→// Derived: all supported extensions
36→export const SUPPORTED_EXTENSIONS = FILE_FORMATS.flatMap((f) => f.extensions);
37→
38→// Derived: human-readable description
39→export const SUPPORTED_EXTENSIONS_TEXT = SUPPORTED_EXTENSIONS.join(", ");
40→
41→// Validator for dropzone
42→export function createFileValidator() {
43→  return (file: File) => {
44→    const ext = file.name
45→      ? "." + (file.name.split(".").pop()?.toLowerCase() || "")
46→      : "";
47→    if (!SUPPORTED_EXTENSIONS.includes(ext)) {
48→      return {
49→        code: "file-invalid-type",
50→        message: `File type not supported. Accepted: ${SUPPORTED_EXTENSIONS_TEXT}`,
51→      };
52→    }
53→    return null;
54→  };
55→}
56→
57→// Parse file content based on extension
58→export function parseFileContent(text: string, filename: string): unknown {
59→  const ext = "." + (filename.split(".").pop()?.toLowerCase() || "");
60→
61→  // Find format by extension
62→  const format = FILE_FORMATS.find((f) => f.extensions.includes(ext));
63→  if (format) {
64→    return format.parse(text);
65→  }
66→
67→  // Fallback: try JSONL detection by content (backwards compat)
68→  if (text.trim().startsWith("{") && text.includes("\n{")) {
69→    return jsonlFormat.parse(text);
70→  }
71→
72→  // Default to JSON
73→  return jsonFormat.parse(text);
74→}
