 33→  /** Custom coloring prompt */
 34→  customColoringPrompt?: string;
 35→}
 36→
 37→/**
 38→ * Result of parsing a conversation
 39→ */
 40→export interface ParseResult {
 41→  conversation: Conversation;
 42→  metadata: ConversationMetadata;
 43→}
 44→
 45→/**
 46→ * Parser interface for converting different API formats to our standard message structure
 47→ */
 48→export interface Parser {
 49→  /** Human-readable name of this parser */
 50→  name: string;
 51→
 52→  /**
 53→   * Parse the input data into our standard Conversation format
 54→   * @param data - The raw API response data
 55→   * @returns Parsed conversation following our schema
 56→   */
 57→  parse(data: unknown): Conversation;
 58→
 59→  /**
 60→   * Extract metadata from the input data (model, provider, etc.)
 61→   * @param data - The raw API response data
 62→   * @returns Metadata about the conversation
 63→   */
 64→  extractMetadata?(data: unknown): Partial<ConversationMetadata>;
 65→
 66→  /**
 67→   * Check if this parser can handle the given data format
 68→   * @param data - The raw data to check
 69→   * @returns true if this parser can handle the data
 70→   */
 71→  canParse(data: unknown): boolean;
 72→}
 73→
 74→/**
 75→ * Registry for managing multiple parser implementations
 76→ */
 77→export class ParserRegistry {
 78→  private parsers: Parser[] = [];
 79→
 80→  /**
 81→   * Register a new parser
 82→   */
 83→  register(parser: Parser): void {
 84→    this.parsers.push(parser);
 85→  }
 86→
 87→  /**
 88→   * Find and use the appropriate parser for the given data
 89→   * @param data - The raw data to parse
 90→   * @returns Parsed conversation (for backwards compatibility)
 91→   * @throws Error if no suitable parser is found
 92→   */
 93→  parse(data: unknown): Conversation {
 94→    const result = this.parseWithMetadata(data);
 95→    return result.conversation;
 96→  }
 97→
 98→  /**
 99→   * Find and use the appropriate parser for the given data, returning metadata
100→   * @param data - The raw data to parse
101→   * @returns ParseResult with conversation and metadata
102→   * @throws Error if no suitable parser is found
103→   */
104→  parseWithMetadata(data: unknown): ParseResult {
105→    const parser = this.parsers.find((p) => p.canParse(data));
106→    if (!parser) {
107→      throw new Error("No suitable parser found for the given data format");
108→    }
109→
110→    const conversation = parser.parse(data);
111→    const extractedMetadata = parser.extractMetadata?.(data) ?? {};
112→
113→    const metadata: ConversationMetadata = {
114→      parserName: parser.name,
115→      ...extractedMetadata,
116→    };
117→
118→    return { conversation, metadata };
119→  }
120→}
121→
122→// Global registry instance
123→export const parserRegistry = new ParserRegistry();
