  1→import type { Conversation } from "@/schema";
  2→import type { ConversationMetadata } from "@/parser";
  3→import {
  4→  SessionExportSchema,
  5→  type SessionExport,
  6→  type FileExport,
  7→  type AnalyticsExport,
  8→  type ExportConversation,
  9→} from "./export-schema";
 10→
 11→/**
 12→ * Minimal WorkflowState interface for export building.
 13→ * Matches the subset of fields we need from the full WorkflowState in App.tsx.
 14→ */
 15→interface WorkflowState {
 16→  id: string;
 17→  filename: string;
 18→  title?: string; // Custom display title
 19→  status?: "pending" | "processing" | "success" | "failed" | "paused-for-api-key";
 20→  conversation?: Conversation;
 21→  componentMapping?: Record<string, string>;
 22→  componentColors?: Record<string, string>;
 23→  aiSummary?: string;
 24→  analysis?: string;
 25→  metadata?: ConversationMetadata;
 26→  isGrouped?: boolean;
 27→  sourceConversations?: Array<{ id: string; filename: string; title?: string }>;
 28→  // Custom prompts
 29→  customPrompt?: string;
 30→  customSegmentationPrompt?: string;
 31→  customSummaryPrompt?: string;
 32→  customAnalysisPrompt?: string;
 33→  customColoringPrompt?: string;
 34→}
 35→
 36→/**
 37→ * Build conversation with component embedded in each part
 38→ */
 39→function buildConversationWithComponents(
 40→  conversation: Conversation,
 41→  componentMapping?: Record<string, string>,
 42→): ExportConversation {
 43→  return {
 44→    messages: conversation.messages.map((message) => ({
 45→      id: message.id,
 46→      role: message.role,
 47→      timestamp: message.timestamp,
 48→      parts: message.parts.map((part) => ({
 49→        ...part,
 50→        component: componentMapping?.[part.id],
 51→      })),
 52→    })),
 53→  };
 54→}
 55→
 56→/**
 57→ * Build export data for a single file/conversation
 58→ */
 59→export function buildFileExport(conv: WorkflowState): FileExport {
 60→  if (!conv.conversation) {
 61→    throw new Error(`Cannot export conversation ${conv.id}: no conversation data`);
 62→  }
 63→
 64→  const conversationWithComponents = buildConversationWithComponents(
 65→    conv.conversation,
 66→    conv.componentMapping,
 67→  );
 68→
 69→  // Build custom prompts object only if any prompts are customized
 70→  const customPrompts = conv.customPrompt || conv.customSegmentationPrompt ||
 71→    conv.customSummaryPrompt || conv.customAnalysisPrompt || conv.customColoringPrompt
 72→    ? {
 73→        componentIdentification: conv.customPrompt,
 74→        segmentation: conv.customSegmentationPrompt,
 75→        summary: conv.customSummaryPrompt,
 76→        analysis: conv.customAnalysisPrompt,
 77→        coloring: conv.customColoringPrompt,
 78→      }
 79→    : undefined;
 80→
 81→  const result: FileExport = {
 82→    id: conv.id,
 83→    filename: conv.filename,
 84→    conversation: conversationWithComponents,
 85→    colors: conv.componentColors || {},
 86→    summary: conv.aiSummary || null,
 87→    analysis: conv.analysis || null,
 88→    metadata: conv.metadata,
 89→    customPrompts,
 90→  };
 91→  if (conv.title) {
 92→    result.title = conv.title;
 93→  }
 94→  return result;
 95→}
 96→
 97→/**
 98→ * Build analytics data from conversations
 99→ */
100→function buildAnalytics(conversations: WorkflowState[]): AnalyticsExport {
101→  return {
102→    componentComparison: conversations.map((conv) => {
103→      const componentTokens: Record<string, number> = {};
104→      let totalTokens = 0;
105→
106→      conv.conversation?.messages.forEach((msg) => {
107→        msg.parts.forEach((part) => {
108→          const tokens = ("token_count" in part && part.token_count) || 0;
109→          const component = conv.componentMapping?.[part.id] || "other";
110→          componentTokens[component] = (componentTokens[component] || 0) + tokens;
111→          totalTokens += tokens;
112→        });
113→      });
114→
115→      const analytics: AnalyticsExport["componentComparison"][number] = {
116→        fileId: conv.id,
117→        filename: conv.filename,
118→        totalTokens,
119→        turnCount:
120→          conv.conversation?.messages.filter((m) => m.role === "user").length ||
121→          0,
122→        messageCount: conv.conversation?.messages.length || 0,
123→        componentTokens,
124→      };
125→      if (conv.title) {
126→        analytics.title = conv.title;
127→      }
128→      return analytics;
129→    }),
130→  };
131→}
132→
133→/**
134→ * Build complete session export from all conversations
135→ */
136→export function buildSessionExport(
137→  conversations: WorkflowState[],
138→): SessionExport {
139→  // Only include successfully processed individual files (not grouped)
140→  const individualFiles = conversations.filter(
141→    (c) => !c.isGrouped && c.status === "success" && c.conversation,
142→  );
143→
144→  // Get grouped conversations
145→  const groups = conversations.filter((c) => c.isGrouped);
146→
147→  const data = {
148→    version: "1.0" as const,
149→    exportedAt: new Date().toISOString(),
150→    files: individualFiles.map(buildFileExport),
151→    groups: groups.map((g) => {
152→      const group: { id: string; name: string; title?: string; fileIds: string[] } = {
